insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-ek-101","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrical conductance of a solution is defined as the","options":["reciprocal of its resistance","product of resistance and cell constant","same quantity as resistivity","reciprocal of molar conductivity"],"answer_index":0,"explanation":"Conductance $G = 1/R$. A smaller resistance means the solution conducts more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-102","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The SI unit used for electrical conductance is the","options":["siemens (S)","ohm ($\\Omega$)","farad (F)","tesla (T)"],"answer_index":0,"explanation":"Siemens is the reciprocal ohm. Older texts also write mho for the same unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-103","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity $\\kappa$ of an electrolyte solution is the conductance of","options":["a unit cube of the solution between opposite faces","one mole of solute placed between inert plates","the salt bridge alone","a metallic wire of the same length"],"answer_index":0,"explanation":"$\\kappa$ is intensive: it is $G$ measured for unit length and unit cross-section of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-104","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The cell constant of a conductivity cell equals","options":["distance between electrodes divided by electrode area","electrode area divided by distance between electrodes","resistance multiplied by current","molar conductivity divided by $\\kappa$"],"answer_index":0,"explanation":"Cell constant $= \\ell/A$. It converts the measured conductance into specific conductivity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-105","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity is obtained from the measured conductance $G$ by writing","options":["$\\kappa = G \\times (\\ell/A)$","$\\kappa = G \\times A/\\ell$","$\\kappa = G^2 \\times \\ell/A$","$\\kappa = (\\ell/A)/G$"],"answer_index":0,"explanation":"Because $G = \\kappa A/\\ell$, rearranging gives $\\kappa = G \\times$ cell constant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-106","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molar conductivity $\\Lambda_m$ is related to specific conductivity and molar concentration $c$ by","options":["$\\Lambda_m = \\kappa/c$","$\\Lambda_m = \\kappa \\times c$","$\\Lambda_m = c/\\kappa$","$\\Lambda_m = \\kappa + c$"],"answer_index":0,"explanation":"In SI, $\\Lambda_m = \\kappa/c$. In older cgs usage one writes $\\Lambda_m = 1000\\,\\kappa/M$ with $M$ in mol L$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-107","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"As an aqueous electrolyte is made more dilute, its specific conductivity $\\kappa$ generally","options":["falls because fewer ions occupy each cubic centimetre","rises because every ion becomes heavier","stays fixed at the value of pure water","becomes equal to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"Dilution lowers the number of charge carriers per unit volume, so $\\kappa$ decreases even though ions may move more freely.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-108","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The usual laboratory unit of cell constant is","options":["cm$^{-1}$","S cm$^2$ mol$^{-1}$","ohm","mol L$^{-1}$"],"answer_index":0,"explanation":"$\\ell/A$ has dimensions of inverse length, so cm$^{-1}$ or m$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-109","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a strong electrolyte such as KCl, further dilution produces","options":["only a modest further rise in $\\Lambda_m$","a sudden drop of $\\Lambda_m$ to zero","no change at all in $\\Lambda_m$","a collapse of $\\kappa$ to a negative value"],"answer_index":0,"explanation":"Strong electrolytes are already fully ionised; $\\Lambda_m$ creeps up mainly because interionic drag weakens.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-110","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Metallic conduction differs from electrolytic conduction in that metals carry current by","options":["mobile electrons, without chemical change of the conductor","migration of cations and anions that are discharged at electrodes","protons hopping through a salt bridge only","neutral solvent molecules drifting in the field"],"answer_index":0,"explanation":"A metal conducts via its electron gas. An electrolyte conducts by ion movement and is chemically changed at the electrodes.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;